fn sqlite_snapshot_semio_mesh_explicit_controlled_native_owner(){use store::{ArtifactPack,ArtifactDsl};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let expected=fixture();for payload in [store::os_io::IoPayload::Binary(expected.encode_pack()),store::os_io::IoPayload::Text(expected.print_dsl())]{let actual=SemioMeshSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(actual,expected);assert!(SemioMeshSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(SemioMeshSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["nativeAdmission"]["tinyBudgetBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());assert!(SemioMeshSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).is_err());}let count=f["nativeAdmission"]["collectionItems"].as_u64().unwrap() as usize;let canceled=f["nativeAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let value=SemioMeshSnapshot{schema:expected.schema,meshes:vec![SemioMesh{id:"mesh".into(),primitives:vec![SemioPrimitive{id:"points".into(),topology:SemioTopology::Points,positions:vec![SemioPoint3{x:-0.0,y:0.0,z:1.0};count],..SemioPrimitive::default()}]}],materials:Vec::new(),textures:Vec::new()};for payload in [store::os_io::IoPayload::Binary(value.encode_pack()),store::os_io::IoPayload::Text(value.print_dsl())]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==count&&p.completed==canceled{interior=true;false}else{true}};assert!(SemioMeshSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(interior);}}

#[test]
fn sqlite_snapshot_semio_mesh_erased_preserves_code_admitted_intermediate_owner(){
 use std::io::Write;use std::process::{Command,Stdio};
 let neutral:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🧩️intermediate/🔣️.json")).unwrap();let input=&neutral["snapshot"];
 let mesh=&input["meshes"][0];let primitive=&mesh["primitives"][0];let material=&input["materials"][0];let snapshot=SemioMeshSnapshot{schema:input["schema"].as_str().unwrap().into(),meshes:vec![SemioMesh{id:mesh["id"].as_str().unwrap().into(),primitives:vec![SemioPrimitive{id:primitive["id"].as_str().unwrap().into(),topology:SemioTopology::Points,positions:Vec::new(),normals:Vec::new(),uvs:Vec::new(),colors:Vec::new(),indices:primitive["indices"].as_array().unwrap().iter().map(|value|u32::try_from(value.as_u64().unwrap()).unwrap()).collect(),material_id:Some(primitive["materialId"].as_str().unwrap().into())}]}],materials:vec![SemioMaterial{id:material["id"].as_str().unwrap().into(),base_color:SemioRgba{r:0.0,g:0.0,b:0.0,a:0.0},metallic:0.0,roughness:0.0,base_color_texture:Some(material["baseColorTexture"].as_str().unwrap().into()),metallic_roughness_texture:Some(material["metallicRoughnessTexture"].as_str().unwrap().into()),normal_texture:Some(material["normalTexture"].as_str().unwrap().into()),occlusion_texture:Some(material["occlusionTexture"].as_str().unwrap().into()),emissive_texture:Some(material["emissiveTexture"].as_str().unwrap().into())}],textures:Vec::new()};
 let provider=<SemioMeshSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"mesh".into()};
 for encoding in [SnapshotEncoding::Text,SnapshotEncoding::Binary]{
  let payload=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioMeshSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioMeshSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};
  assert_eq!(SemioMeshSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),snapshot);
  let db=(provider.export)("s.stdio.semio.mesh",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(restore(&db).unwrap(),snapshot);
  let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const f=JSON.parse(process.argv[1]);const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));try{if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(JSON.stringify(db.query(f.query).all())!==JSON.stringify(f.expectedRows))throw Error('full query');await Bun.write(Bun.stdout,db.serialize());}finally{db.close();}";
  let text=serde_json::to_string(&neutral).unwrap();let mut child=Command::new("bun").args(["-e",script,&text]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
  let db=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let result=(provider.import)("s.stdio.semio.mesh",&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
  assert_eq!(SemioMeshSnapshot::decode_sqlite_snapshot_native(&result,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),snapshot);
 }
